   var bad=null, so=0, co=CAREER_ON, ts, i;
   function fr(n){ for(var k=0;k<n;k++){ ts+=50; HID.fromWorker=1; try{ loop(ts); } finally{ HID.fromWorker=0; } } }
   try{
     __topClear(); __runPrep(); CAREER_ON=0; arcadeSoloPick();
     if(!arcadeDeploy({mapIx:0,seed:5})||!G||!G.arcade||!G.player) return 'SKIP: no arcade raid was built';
     so=ARCADE.solo; ARCADE.solo=0; ts=performance.now()+100000; fr(5);
     pwrS().act.clip=20; pwrS().act.shield=10;
     killPlayer('test'); fr(80);
     if(!G||!G.player||G.player.dying||G.over) bad='SKIP: the player did not respawn in the 2 player rules';
     else if(pwrOn('clip')||pwrOn('shield')) bad='after a death and respawn the power-ups still run (clip '+(G.pwr.act.clip||0).toFixed(1)+' s, shield '+(G.pwr.act.shield||0).toFixed(1)+' s)';
   } finally {
     try{ ARCADE.solo=so; if(G&&G.arcade&&!G.over) arcadeRaidStop('end'); }catch(_e){}
     CAREER_ON=co; __topClear();
   }
   return bad; }},
